package main

import (
	"fmt"
	"io"
	"net/http"
	"os"
	"strconv"
	"time"
)

var mode string

func main() {
	mode = os.Getenv("MODE")
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		f, _ := os.OpenFile("/tmp/srv/golog.txt", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
		fmt.Fprintf(f, "=== REQUEST ===\n%s %s %s\n", r.Method, r.URL.RequestURI(), r.Proto)
		for k, v := range r.Header {
			for _, vv := range v {
				fmt.Fprintf(f, "%s: %s\n", k, vv)
			}
		}
		fmt.Fprintf(f, "--- body len=%d ---\n%q\n=== END ===\n", len(body), body)
		f.Close()
		q := r.URL.Query()
		st := 200
		if v := q.Get("status"); v != "" {
			st, _ = strconv.Atoi(v)
		}
		resp := []byte(`{"hello": "world", "n": 123}`)
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("X-Test", "yes")
		w.Header().Set("Date", "Thu, 01 Jan 2026 00:00:00 GMT")
		w.Header().Set("Server", "mytest/1.0")
		w.WriteHeader(st)
		w.Write(resp)
		_ = time.Now()
	})
	http.ListenAndServe("127.0.0.1:8916", nil)
}
EOF
