actions.command:
cat <<'EOF' > /tmp/probe/main.go
package main

import (
	"fmt"
	"io"
	"net/http"
	"strings"
)

func main() {
	inputs := []string{":///", "://x", ":8080/", "://", ":/", ":", "//x", "///x", "ftp://h/p", "HTTP://h/p", "127.0.0.1:9999", "localhost:9999/x", "http://", "https://h/", "/path", "a:///b", "x://"}
	for _, in := range inputs {
		raw := in
		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
			raw = "http://" + raw
		}
		resp, err := http.Get(raw)
		if err != nil {
			fmt.Printf("%-20q -> ERR %v\n", in, err)
			continue
		}
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%-20q -> OK %d %q\n", in, resp.StatusCode, string(b))
	}
}
EOF
cd /tmp/probe && export GOPATH=/tmp/gopath GOCACHE=/tmp/gocache && timeout 120 go run . 2>&1 | head -25

