{"command": "mkdir -p /workspace/src && cat <<'GOEOF' > /workspace/src/filter.go
package main

import (
	"log"
	"strings"
)

// Request holds the pieces of an HTTP request exactly as they were spelled out
// on the command line.  A command line looks like
//
//	bat [METHOD] URL [ITEM [ITEM]]
//
// where every ITEM is either a header (key:value), a data field (key=value) or
// a file upload (key@/path/to/file).
type Request struct {
	Method  string
	URL     string
	Headers map[string]string
	Data    map[string]string
	Files   map[string]string
}

// knownMethods is the set of HTTP verbs that are recognised as the first
// command line argument.  Anything else is treated as the request URL.
var knownMethods = map[string]bool{
	"GET":    true,
	"POST":   true,
	"PUT":    true,
	"DELETE": true,
	"PATCH":  true,
	"HEAD":   true,
}

// isMethod reports whether the given argument looks like an HTTP verb.
func isMethod(arg string) bool {
	return knownMethods[strings.ToUpper(arg)]
}

// parseArgs walks the command line arguments and splits them into the method,
// the URL and the individual request items.
func parseArgs(args []string) *Request {
	req := &Request{
		Headers: make(map[string]string),
		Data:    make(map[string]string),
		Files:   make(map[string]string),
	}
	if len(args) > 0 && isMethod(args[0]) {
		req.Method = strings.ToUpper(args[0])
		args = args[1:]
	}
	if len(args) == 0 {
		log.Fatal("Miss the URL") //__LOG35
	}
	req.URL = args[0]
	for _, item := range args[1:] {
		switch {
		case strings.Contains(item, ":"):
			parts := strings.SplitN(item, ":", 2)
			req.Headers[parts[0]] = parts[1]
		case strings.Contains(item, "="):
			parts := strings.SplitN(item, "=", 2)
			req.Data[parts[0]] = parts[1]
		case strings.Contains(item, "@"):
			parts := strings.SplitN(item, "@", 2)
			req.Files[parts[0]] = parts[1]
		}
	}
	if req.Method == "" {
		if len(req.Data) > 0 || len(req.Files) > 0 {
			req.Method = "POST"
		} else {
			req.Method = "GET"
		}
	}
	return req
}
GOEOF
