	flag.StringVar(&opts.auth, "a", "", "Pass a username:password pair as the argument")
	flag.StringVar(&opts.auth, "auth", "", "Pass a username:password pair as the argument")
	flag.BoolVar(&opts.bench, "b", false, "Sends bench requests to URL")
	flag.BoolVar(&opts.bench, "bench", false, "Sends bench requests to URL")
	flag.IntVar(&opts.benchN, "b.N", 1000, "Number of requests to run")
	flag.IntVar(&opts.benchC, "b.C", 100, "Number of requests to run concurrently")
	flag.StringVar(&opts.body, "body", "", "Send RAW data as body")
	flag.BoolVar(&opts.download, "download", false, "Download the response body into a file")
	flag.BoolVar(&opts.form, "f", false, "Submitting the data as a form")
	flag.BoolVar(&opts.form, "form", false, "Submitting the data as a form")
	flag.BoolVar(&opts.insecure, "i", false, "Allow connections to SSL sites without certs")
	flag.BoolVar(&opts.insecure, "insecure", false, "Allow connections to SSL sites without certs")
	flag.BoolVar(&opts.json, "json", true, "Send the data in a JSON object")
	flag.BoolVar(&opts.pretty, "p", true, "Print Json Pretty Format")
	flag.BoolVar(&opts.pretty, "pretty", true, "Print Json Pretty Format")
	flag.StringVar(&opts.proxy, "proxy", "", "Proxy with host and port")
	flag.StringVar(&printFlag, "print", "A", "String specifying what the output should contain")
	flag.BoolVar(&opts.version, "v", false, "Show Version Number")
	flag.BoolVar(&opts.version, "version", false, "Show Version Number")

	log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)
