// newTransport builds the http.Transport used for a single run.  It honours the
// -insecure and -proxy switches and makes sure the gzip/deflate encodings are
// announced but decompressed by hand.
func newTransport(insecure bool, proxy string) *http.Transport {
	tr := &http.Transport{
		ResponseHeaderTimeout: 60 * time.Second,
	}
	if insecure {
		tr.TLSClientConfig = tlsSkipVerify()
	}
	if proxy != "" {
		u, err := url.Parse(proxy)
		if err != nil {
			log.Fatal("Proxy Url parse err", err) //__LOG182
		}
		tr.Proxy = http.ProxyURL(u)
	}
	return tr
}

// normalizeURL applies bat's URL shorthand: the http:// scheme is added when it
// is missing and an empty host part falls back to localhost.
func normalizeURL(raw string) string {
	if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
		raw = "http://" + raw
	}
