	}
	return io.ReadAll(resp.Body)
}

// isJSONContentType reports whether the answer should be handled as JSON.
func isJSONContentType(ct string) bool {
	return strings.HasPrefix(ct, "application/") && strings.Contains(ct, "json")
}

// printColoredHeaders renders the status line and the response headers with a
// little bit of colour so that they stand out.
func printColoredHeaders(resp *http.Response) {
	fmt.Printf("\033[95m%s\033[0m \033[92m%s\033[0m\n", resp.Proto, resp.Status)
	for key, values := range resp.Header {
		fmt.Printf("\033[90m%s\033[0m : \033[96m%s\033[0m\n", key, strings.Join(values, " "))
	}
	fmt.Println()
}
