package main

import (
	"bytes"
	"crypto/tls"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"mime/multipart"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"
)

// skipTLSVerify builds the TLS client configuration used by -insecure.
func skipTLSVerify() *tls.Config {
	return &tls.Config{InsecureSkipVerify: true}
}

// applyAuth installs the Authorization header described by the -a switch.  The
// value is either "user" (the password is left empty) or "user:password"; a
// password may itself contain colons, only the first one is significant.
func applyAuth(header http.Header, auth string) {
	if auth == "" {
		return
	}
	user, pass := auth, ""
	if i := strings.Index(auth, ":"); i >= 0 {
		user, pass = auth[:i], auth[i+1:]
	}
	token := base64Token(user + ":" + pass)
	header.Set("Authorization", "Basic "+token)
}

// base64Token encodes a "user:password" pair the way RFC 7617 prescribes.
func base64Token(pair string) string {
	return base64.StdEncoding.EncodeToString([]byte(pair))
}

// nopCloserReader hides the length of the buffer so that the transport falls
// back to chunked transfer encoding.
func nopCloserReader(buffer *bytes.Buffer) io.ReadCloser {
	return io.NopCloser(bytes.NewReader(buffer.Bytes()))
}

// encodeForm renders the data fields the way a classic HTML form would.  Both
// the name and the value are query escaped, keys are emitted in an arbitrary
// order because the command line gives them in a map.
func encodeForm(data map[string]string) []byte {
	var out bytes.Buffer
	for key, value := range data {
		if out.Len() > 0 {
			out.WriteByte('&')
		}
		out.WriteString(url.QueryEscape(key))
		out.WriteByte('=')
		out.WriteString(url.QueryEscape(value))
	}
	return out.Bytes()
}

// encodeJSON renders the data fields as a JSON object.  Values are always
// strings, exactly like the command line spelled them out.
func encodeJSON(data map[string]string) []byte {
	encoded, err := json.Marshal(data)
	if err != nil {
		return []byte("{}\n")
	}
	return append(encoded, '\n')
}

// writeMultipart streams the file uploads first and the plain data fields after
// them, which is the order the original tool uses.
func writeMultipart(mw *multipart.Writer, files map[string]string, data map[string]string) {
	for name, path := range files {
		writer, err := mw.CreateFormFile(name, path)
		if err != nil {
			log.Fatal(err)
		}
		writer.Write(readUpload(path))
	}
	for name, value := range data {
		writer, err := mw.CreateFormField(name)
		if err != nil {
			log.Fatal(err)
		}
		writer.Write([]byte(value))
	}
	mw.Close()
}

// readUpload loads a file that is about to be uploaded.  Failures are fatal,
// mirroring the behaviour of the original implementation.
func readUpload(path string) []byte {
	file, err := os.Open(path)
	if err != nil {
		log.Fatal(err) //__LOG328
	}
	defer file.Close()
	// The content is slurped in one go; uploads are expected to be small
	// enough to fit into memory comfortably.
	content, err := io.ReadAll(file)
	if err != nil {
		log.Fatal(err) //__LOG334
	}
	return content
}

// fileNameOf derives the download file name from the path component of an URL.
// Everything up to the last slash is dropped, which means a URL that ends in a
// slash yields an empty name and therefore cannot be downloaded.
func fileNameOf(raw string) string {
	u, err := url.Parse(raw)
	if err != nil {
		return ""
	}
	parts := strings.Split(u.Path, "/")
	return parts[len(parts)-1]
}

// byteUnits are the suffixes used when rendering a byte count for humans.  The
// list stops at gigabytes, larger amounts simply keep being expressed in GB.
var byteUnits = []string{"B", "KB", "MB", "GB"}

// formatBytes renders a byte count the way the progress bar wants it: plain
// integers below one kilobyte, two decimals afterwards.
func formatBytes(value float64) string {
	unit := 0
	for value > 1024 && unit < len(byteUnits)-1 {
		value /= 1024
		unit++
	}
	if unit == 0 {
		return fmt.Sprintf("%d B", int64(value))
	}
	return fmt.Sprintf("%.2f %s", value, byteUnits[unit])
}

// lineWidth is the total width the progress bar tries to occupy.  The bar
// itself is shrunk or grown so that the whole line always has this length.
const lineWidth = 123

// barFrame is rendered when the total size of the download is unknown: there is
// no bar, no percentage and no estimate, only the counters and the speed.
const unknownBarPad = 105

// progressBar tracks how many bytes have been copied and draws itself as a
// single line that is continuously overwritten.
type progressBar struct {
	total    int64
	current  int64
	start    time.Time
	lastTick time.Time
	lastRate float64
}

// newProgressBar prepares a bar for a transfer of the given total size.  A
// total of zero means "unknown", which switches the bar into its compact form.
func newProgressBar(total int64) *progressBar {
	now := time.Now()
	return &progressBar{total: total, start: now, lastTick: now}
}

// Write implements io.Writer so that the bar can be plugged into an io.Copy
// straight away.
func (b *progressBar) Write(p []byte) (int, error) {
	n := len(p)
	b.current += int64(n)
	b.maybeDraw()
	return n, nil
}

// maybeDraw redraws the line at most every two hundred milliseconds.
func (b *progressBar) maybeDraw() {
	now := time.Now()
	if now.Sub(b.lastTick) < 200*time.Millisecond {
		return
	}
	b.lastTick = now
	b.draw()
}

// finish renders the very last state of the bar, replacing the estimate with
// the time the transfer actually took.
func (b *progressBar) finish() {
	b.draw()
}

// draw renders the current state of the bar on stdout.
func (b *progressBar) draw() {
	elapsed := time.Since(b.start)
	rate := 0.0
	if elapsed > 0 {
		rate = float64(b.current) / elapsed.Seconds()
	}
	speed := formatBytes(rate) + "/s"
	if b.total <= 0 {
		fmt.Printf("\r%s %s %s%s", formatBytes(float64(b.current)), speed,
			formatDuration(elapsed), strings.Repeat(" ", unknownBarPad))
		return
	}
	percent := 0.0
	if b.total > 0 {
		percent = float64(b.current) / float64(b.total) * 100
	}
	eta := int64(0)
	if b.current < b.total {
		if rate > 0 {
			eta = int64(float64(b.total-b.current) / rate)
		}
	} else {
		eta = int64(elapsed.Seconds())
	}
	prefix := fmt.Sprintf("%s / %s ", formatBytes(float64(b.current)), formatBytes(float64(b.total)))
	suffix := fmt.Sprintf(" %.2f %% %s %s", percent, speed, formatDuration(time.Duration(eta)*time.Second))
	fmt.Printf("\r%s[%s]%s", prefix, renderBar(percent, lineWidth-len(prefix)-len(suffix)-2), suffix)
}

// renderBar paints the progress bar itself: completed cells are drawn with
// '=', the cell currently being filled with '>' and the remaining ones with '_'.
func renderBar(percent float64, width int) string {
	if width < 1 {
		return ""
	}
	filled := int(percent / 100 * float64(width))
	if filled > width {
		filled = width
	}
	if filled >= width {
		return strings.Repeat("=", width)
	}
	return strings.Repeat("=", filled) + ">" + strings.Repeat("_", width-filled-1)
}

// formatDuration renders a duration the way the progress bar and the bench
// report want it: whole seconds only.
func formatDuration(d time.Duration) string {
	return (time.Duration(int64(d.Seconds())) * time.Second).String()
}
