	fmt.Printf("  Response Size per Request:\t%d bytes.\n", stats.sizePerReq)
}

// printStatusCodes renders the distribution of the observed status codes.
func printStatusCodes(codes map[int]int) {
	fmt.Printf("\nStatus code distribution:\n")
	for code, count := range codes {
		fmt.Printf("  [%d]\t%d responses\n", code, count)
	}
}

// printErrorDistribution renders the block of transport level failures.
func printErrorDistribution(errs map[string]int) {
	fmt.Printf("\nError distribution:\n")
	for message, count := range errs {
		fmt.Printf("  [%d]\t%s\n", count, message)
	}
