// histogramBuckets splits the observed latencies into eleven buckets.  The
// outermost bounds are the fastest and the slowest request, the inner ones are
// evenly spaced in between.
func histogramBuckets(latencies []float64, fastest, slowest float64) (bounds []float64, counts []int) {
	bounds = make([]float64, 11)
	counts = make([]int, 11)
	span := slowest - fastest
	for i := range bounds {
		bounds[i] = fastest + float64(i)*span/10
	}
	for _, value := range latencies {
		bucket := 0
		if span > 0 {
			bucket = int(math.Ceil((value - fastest) / span * 10))
		}
		if bucket > 10 {
			bucket = 10
		}
		if bucket < 0 {
			bucket = 0
		}
		counts[bucket]++
	}
	return bounds, counts
}

// printHistogram renders the response time histogram.  Each row shows the lower
// bound of the bucket, how many requests fell into it and a bar whose length is
// proportional to the busiest bucket.
func printHistogram(latencies []float64, fastest, slowest float64) {
	fmt.Printf("\nResponse time histogram:\n")
	bounds, counts := histogramBuckets(latencies, fastest, slowest)
	busiest := 0
	for _, count := range counts {
		if count > busiest {
			busiest = count
		}
	}
	for i, bound := range bounds {
		bar := 0
		if busiest > 0 {
			bar = int(float64(counts[i]) * histogramBars / float64(busiest))
		}
		fmt.Printf("  %.3f [%d]\t|%s\n", bound, counts[i], strings.Repeat(histogramBlocks, bar))
	}
}

// printLatencyDistribution renders the percentiles of the observed latencies.
// Percentiles that would need more samples than the run produced are skipped.
func printLatencyDistribution(latencies []float64) {
	sorted := make([]float64, len(latencies))
	copy(sorted, latencies)
	sort.Float64s(sorted)
	fmt.Printf("\nLatency distribution:\n")
	total := len(sorted)
	previous := 0
	for _, pct := range []int{10, 25, 50, 75, 90, 95, 99} {
		index := int(math.Ceil(float64(total) * float64(pct) / 100))
		if index <= previous {
			index = previous + 1
		}
		if index >= total {
			break
		}
		fmt.Printf("  %d%% in %.4f secs.\n", pct, sorted[index])
		previous = index
	}
}

// printReport renders the whole benchmark report, histograms and percentiles
// included, and appends the error distribution when something went wrong.
func printReport(stats *benchStats) {
	if len(stats.latencies) == 0 {
		printErrorDistribution(stats.errs)
		return
	}
	printSummary(stats)
	printStatusCodes(stats.codes)
	printHistogram(stats.latencies, stats.fastest, stats.slowest)
	printLatencyDistribution(stats.latencies)
	if len(stats.errs) > 0 {
		printErrorDistribution(stats.errs)
	}
}
