{"command": "cat <<'GOEOF' > /workspace/src/bench.go
package main

import (
	"io"
	"net/http"
	"sync"
	"time"
)

// runBench fires the very same request n times with at most c of them in flight
// and prints a report about what happened.
func runBench(client *http.Client, opts *runOptions, n, c int) {
	if c < 1 {
		c = 1
	}
	stats := &benchStats{codes: make(map[int]int), errs: make(map[string]int)}
	var mu sync.Mutex
	var wg sync.WaitGroup
	slots := make(chan struct{}, c)

	started := time.Now()
	fastest := time.Duration(1<<63 - 1)
	slowest := time.Duration(0)
	succeeded := 0

	for i := 0; i < n; i++ {
		slots <- struct{}{}
		wg.Add(1)
		go func() {
			defer wg.Done()
			defer func() { <-slots }()

			began := time.Now()
			request, err := buildRequest(opts)
			if err != nil {
				mu.Lock()
				stats.errs[err.Error()]++
				mu.Unlock()
				return
			}
			resp, err := client.Do(request)
			if err != nil {
				mu.Lock()
				stats.errs[err.Error()]++
				mu.Unlock()
				return
			}
			body, readErr := io.ReadAll(resp.Body)
			resp.Body.Close()
			spent := time.Since(began)

			mu.Lock()
			defer mu.Unlock()
			if readErr != nil {
				stats.errs[readErr.Error()]++
				return
			}
			succeeded++
			stats.codes[resp.StatusCode]++
			stats.latencies = append(stats.latencies, spent.Seconds())
			stats.totalData += int64(len(body))
			if spent < fastest {
				fastest = spent
			}
			if spent > slowest {
				slowest = spent
			}
		}()
	}
	wg.Wait()
	stats.total = time.Since(started)

	if succeeded > 0 {
		stats.fastest = fastest
		stats.slowest = slowest
		stats.average = time.Duration(int64(stats.total) / int64(n))
		stats.rps = float64(succeeded) / stats.total.Seconds()
		stats.sizePerReq = stats.totalData / int64(succeeded)
	}
	printReport(stats)
}
