new = '''// normalizeURL adds the http:// scheme when it is missing.
func normalizeURL(raw string) string {
	if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
		raw = "http://" + raw
	}
	raw = fixEmptyHost(raw)
	u, err := url.Parse(raw)
	if err != nil {
		log.Fatal(err) //__LOG158
	}
	return u.String()
}

// fixEmptyHost rewrites a URL whose host part is missing but not absent, that
// is a URL like "http://:8080/x" where the host name is empty.  Such a host is
// replaced by localhost so that the request has somewhere to go.
func fixEmptyHost(raw string) string {
	i := strings.Index(raw, "://")
	if i < 0 {
		return raw
	}
	rest := raw[i+3:]
	j := strings.IndexAny(rest, "/?#")
	var host, tail string
	if j < 0 {
		host, tail = rest, ""
	} else {
		host, tail = rest[:j], rest[j:]
	}
	if !strings.HasPrefix(host, ":") {
		return raw
	}
	if host == ":" {
		host = "localhost"
		if tail == "" {
			tail = "/"
		}
	} else {
		host = "localhost" + host
	}
	return raw[:i+3] + host + tail
}

'''
s = s[:old_start] + new + s[old_end:]
open(p,'w',encoding='utf-8').write(s)
