// runOptions carries every command line switch of the tool.
type runOptions struct {
	method   string
	url      string
	headers  map[string]string
	data     map[string]string
	files    map[string]string
	auth     string
	body     string
	form     bool
	json     bool
	pretty   bool
	insecure bool
	proxy    string
	download bool
	bench    bool
	benchN   int
	benchC   int
	version  bool
}

// The URL argument is the only thing bat really insists on, but it accepts a
// rather loose spelling of it:
//
//	bat example.org            -> http://example.org
//	bat example.org:8080/x     -> http://example.org:8080/x
//	bat https://example.org/   -> https://example.org/ (kept as written)
//	bat ftp://example.org/     -> http://ftp://example.org/ (still "ftp" host)
//
// The scheme is added only when neither "http://" nor "https://" is already
// present, and the comparison is case sensitive: "HTTP://x" is not a scheme.
//
// A second shorthand concerns URLs whose authority is empty or starts with a
// colon, such as "http://:8080/x".  Such a URL has nowhere to go, so the host
// is replaced by localhost while the rest of the URL is left untouched:
//
//	http://:8080/x   -> http://localhost:8080/x
//	http://:///x     -> http://localhost///x
//	http://ftp:/     -> http://ftp:/     (a host of "ftp:" is left alone)
//
// The rewrite happens on the textual form of the URL, before it is parsed, so
// that a malformed authority is still reported against the rewritten text.
//
// normalizeURL applies the shorthands described above and returns the textual
// form of the URL that should be used for the request.
func normalizeURL(raw string) string {
	if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
		raw = "http://" + raw
	}
	raw = fixEmptyHost(raw)
	u, err := url.Parse(raw)
	if err != nil {
		log.Fatal(err) //__LOG158
	}
	return u.String()
}

// newTransport builds the http.Transport used for a run.  It honours the
// -insecure and -proxy switches and always installs a generous header timeout.
func newTransport(insecure bool, proxy string) *http.Transport {
	tr := &http.Transport{
		ResponseHeaderTimeout: 60 * time.Second,
	}
	if insecure {
		tr.TLSClientConfig = skipTLSVerify()
	}
	if proxy != "" {
		u, err := url.Parse(proxy)
		if err != nil {
			log.Fatal("Proxy Url parse err", err) //__LOG182
		}
		tr.Proxy = http.ProxyURL(u)
	}
	return tr
}

// fixEmptyHost rewrites a URL like "http://:8080/x" where the host name is
// empty: such a host is replaced by localhost.
func fixEmptyHost(raw string) string {
	i := strings.Index(raw, "://")
	if i < 0 {
		return raw
	}
	rest := raw[i+3:]
	j := strings.IndexAny(rest, "/?#")
	var host, tail string
	if j < 0 {
		host, tail = rest, ""
	} else {
		host, tail = rest[:j], rest[j:]
	}
	if !strings.HasPrefix(host, ":") {
		return raw
	}
	if host == ":" {
		host = "localhost"
		if tail == "" {
			tail = "/"
		}
	} else {
		host = "localhost" + host
	}
	return raw[:i+3] + host + tail
}

// doRequest performs a single request and aborts the program when the transport
// refuses to talk to us.
func doRequest(client *http.Client, request *http.Request) *http.Response {
	resp, err := client.Do(request)
	if err != nil {
		log.Fatal("can't get the url ", err) //__LOG215
	}
	return resp
}

// downloadTo streams the response body into a file named after the request URL
// while showing a progress bar.
func downloadTo(resp *http.Response, rawURL string) {
	name := fileNameOf(normalizeURL(rawURL))
	file, err := os.Create(name)
	if err != nil {
		log.Fatal("can't create file", err) //__LOG240
	}
	defer file.Close()

	printColoredHeaders(resp)
	fmt.Printf("Downloading to %q\n", name)

	bar := newProgressBar(resp.ContentLength)
	if _, err := io.Copy(io.MultiWriter(file, bar), resp.Body); err != nil {
		log.Fatal("Can't Write the body into file", err) //__LOG265
	}
	bar.finish()
}

func main() {
	var opts runOptions
	fs := flag.NewFlagSet("", flag.ContinueOnError)
	fs.Usage = func() { fmt.Print(usage) }
	fs.StringVar(&opts.auth, "a", "", "Pass a username:password pair as the argument")
	fs.StringVar(&opts.auth, "auth", "", "Pass a username:password pair as the argument")
	fs.BoolVar(&opts.bench, "b", false, "Sends bench requests to URL")
	fs.BoolVar(&opts.bench, "bench", false, "Sends bench requests to URL")
	fs.IntVar(&opts.benchN, "b.N", 1000, "Number of requests to run")
	fs.IntVar(&opts.benchC, "b.C", 100, "Number of requests to run concurrently")
	fs.StringVar(&opts.body, "body", "", "Send RAW data as body")
	fs.BoolVar(&opts.download, "download", false, "Download the response body into a file")
	fs.BoolVar(&opts.form, "f", false, "Submitting the data as a form")
	fs.BoolVar(&opts.form, "form", false, "Submitting the data as a form")
	fs.BoolVar(&opts.insecure, "i", false, "Allow connections to SSL sites without certs")
	fs.BoolVar(&opts.insecure, "insecure", false, "Allow connections to SSL sites without certs")
	fs.BoolVar(&opts.json, "json", true, "Send the data in a JSON object")
	fs.BoolVar(&opts.pretty, "p", true, "Print Json Pretty Format")
	fs.BoolVar(&opts.pretty, "pretty", true, "Print Json Pretty Format")
	fs.StringVar(&opts.proxy, "proxy", "", "Proxy with host and port")
	fs.StringVar(&printFlag, "print", "A", "String specifying what the output should contain")
	fs.BoolVar(&opts.version, "v", false, "Show Version Number")
	fs.BoolVar(&opts.version, "version", false, "Show Version Number")

	log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)
	if err := fs.Parse(os.Args[1:]); err != nil {
		os.Exit(2)
	}

	if opts.version {
		fmt.Println("Version: " + VERSION)
		os.Exit(2)
	}
	args := fs.Args()
	if len(args) == 0 {
		fmt.Print(usage)
		os.Exit(2)
	}

	req := parseArgs(args)
	opts.method, opts.url = req.Method, req.URL
	opts.headers, opts.data, opts.files = req.Headers, req.Data, req.Files

	request, err := buildRequest(&opts)
	if err != nil {
		log.Fatal(err)
	}

	client := &http.Client{Transport: newTransport(opts.insecure, opts.proxy)}

	if opts.bench {
		runBench(client, &opts, opts.benchN, opts.benchC)
		return
	}

	resp := doRequest(client, request)
	defer resp.Body.Close()

	if opts.download {
		downloadTo(resp, req.URL)
		return
	}
	printResponse(resp, opts.pretty)
}
